package com.aac.ieojwo.routine.service;
import com.aac.ieojwo.alert.domain.AlertType;import com.aac.ieojwo.alert.service.AlertService;import com.aac.ieojwo.common.exception.*;import com.aac.ieojwo.live.LiveEventService;import com.aac.ieojwo.routine.domain.Routine;import com.aac.ieojwo.routine.repository.RoutineRepository;import com.aac.ieojwo.user.domain.AacUser;import com.aac.ieojwo.user.service.AacUserAccessService;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Transactional(readOnly=true)
public class RoutineService{public record RoutineRequest(String title,String message,LocalTime timeOfDay,Set<DayOfWeek> daysOfWeek,String timezone,boolean enabled){}public record RoutineResponse(Long id,String title,String message,LocalTime timeOfDay,Set<String> daysOfWeek,String timezone,boolean enabled,LocalDate lastTriggeredDate){static RoutineResponse from(Routine r){return new RoutineResponse(r.getId(),r.getTitle(),r.getMessage(),r.getTimeOfDay(),Set.of(r.getDaysOfWeek().split(",")),r.getTimezone(),r.isEnabled(),r.getLastTriggeredDate());}}private final RoutineRepository repo;private final AacUserAccessService access;private final AlertService alerts;private final LiveEventService live;public RoutineService(RoutineRepository r,AacUserAccessService a,AlertService alerts,LiveEventService live){repo=r;access=a;this.alerts=alerts;this.live=live;}public List<RoutineResponse> list(OidcUser p,Long id){access.requireAccessibleUser(p,id);return repo.findAllByUserIdOrderByTimeOfDayAsc(id).stream().map(RoutineResponse::from).toList();}@Transactional public RoutineResponse save(OidcUser p,Long id,Long rid,RoutineRequest q){AacUser u=access.requireAccessibleUser(p,id);validate(q);String days=q.daysOfWeek().stream().map(Enum::name).sorted().reduce((a,b)->a+","+b).orElseThrow();Routine r=rid==null?repo.save(Routine.create(u,q.title(),q.message(),q.timeOfDay(),days,q.timezone())):owned(u,rid);r.apply(q.title(),q.message(),q.timeOfDay(),days,q.timezone(),q.enabled());return RoutineResponse.from(r);}@Transactional public void delete(OidcUser p,Long id,Long rid){AacUser u=access.requireAccessibleUser(p,id);owned(u,rid).disable();}@Scheduled(fixedDelay=30000)@Transactional public void trigger(){for(Routine r:repo.findAllByEnabledTrue()){ZonedDateTime now=ZonedDateTime.now(ZoneId.of(r.getTimezone()));if(r.due(now)){r.triggered(now.toLocalDate());alerts.create(r.getUser(),AlertType.ROUTINE,r.getTitle(),r.getMessage());live.publish(r.getUser().getId(),"ROUTINE_TRIGGERED",RoutineResponse.from(r));}}}private Routine owned(AacUser u,Long id){Routine r=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("루틴을 찾을 수 없습니다."));if(!r.getUser().getId().equals(u.getId()))throw new ForbiddenException("다른 사용자의 루틴입니다.");return r;}private void validate(RoutineRequest r){if(r.title()==null||r.title().isBlank()||r.message()==null||r.message().isBlank()||r.timeOfDay()==null||r.daysOfWeek()==null||r.daysOfWeek().isEmpty())throw new BadRequestException("루틴 제목, 메시지, 시간, 요일은 필수입니다.");try{ZoneId.of(r.timezone());}catch(Exception e){throw new BadRequestException("유효하지 않은 타임존입니다.");}}}
